def combine(self, raw: Mapping[str, float]) -> float:
    c, n = self.cfg, self.norm
    # the waiting term is already signed (less waiting = positive); the others are costs
    r = raw["wait"] / n["wait"] if c.base == "wait" else -raw[c.base] / n[c.base]
    if c.co2:
        r -= c.co2 * raw["co2"] / n["co2"]
    if c.ev:
        r -= c.ev * raw["ev"] / n["ev"]
    if c.ped:
        r -= c.ped * raw["ped"] / n["ped"]
    return float(np.clip(r, -c.clip, c.clip))

def block_sizes(cfg: ObservationConfig, pad: Padding) -> dict[str, int]:
    sizes = {
        "lanes": 4 * pad.lanes_per_side * 3,
        "phase": 3 * pad.max_phases + 2,
    }
    if cfg.neighbours:
        sizes["neighbours"] = 4 * MESSAGE_SIZE
    if cfg.emergency:
        sizes["emergency"] = 4 * 2 + pad.max_phases
    if cfg.pedestrians:
        sizes["pedestrians"] = pad.max_crossings
    if cfg.buses:
        sizes["buses"] = 4
    if cfg.forecast:
        sizes["forecast"] = 4
    return sizes

def act(self, env, obs: dict[str, Any]) -> dict[str, int]:
    actions = {}
    for tid, inter in env.intersections.items():
        weights = phase_pressure(inter, env.meas)
        best = max(weights)
        actions[tid] = inter.phase if weights[inter.phase] >= best else weights.index(best)
    return actions

def approaching(env, signals, range_m: float) -> dict[str, tuple[float, int]]:
    """Closest approaching emergency vehicle per signal: (distance, link index)."""
    out: dict[str, tuple[float, int]] = {}
    for ev in env.ev_ids:
        upcoming = env.conn.vehicle.getNextTLS(ev)
        if not upcoming:
            continue
        tls, link, dist, _ = upcoming[0]
        if tls in signals and dist <= range_m and (tls not in out or dist < out[tls][0]):
            out[tls] = (dist, link)
    return out

def requests(self, env) -> dict[str, int]:
    found = approaching(env, env.intersections, self.range_m)
    self.preemptions += len(set(found) - self.active)
    self.active = set(found)
    return {tid: phase_for(env.intersections[tid], link) for tid, (_, link) in found.items()}

def apply_shield(requested: int, state: ShieldState, cfg: ShieldConfig) -> ShieldDecision:
    """Return the phase to execute given the controller's ``requested`` phase.

    ``phase_demand[p]`` is the demand that phase ``p`` would serve beyond what the
    current phase already serves; it picks the target when the shield must switch.
    """
    current = state.current_phase  # [Exigence 9] bouclier : vert min, anti-famine, vert max
    reason: str | None = None
    if not 0 <= requested < state.n_phases:
        requested, reason = current, INVALID

    if state.green_elapsed < cfg.min_green:
        return ShieldDecision(current, MIN_GREEN if requested != current else reason)

    starving = [
        link
        for link in state.links_with_demand
        if state.link_red_time.get(link, 0.0) > cfg.max_red
        and link not in state.phase_links[current]
        and any(link in links for links in state.phase_links)
    ]
    if starving:
        worst = max(starving, key=lambda link: (state.link_red_time[link], -link))
        if worst in state.phase_links[requested]:
            return ShieldDecision(requested, reason)
        candidates = [p for p in range(state.n_phases) if worst in state.phase_links[p]]
        target = max(
            candidates,
            key=lambda p: (
                sum(link in state.phase_links[p] for link in starving),
                state.phase_demand[p],
                -p,
            ),
        )
        return ShieldDecision(target, STARVATION)

    if requested == current and state.green_elapsed >= cfg.max_green:
        others = [p for p in range(state.n_phases) if p != current and state.phase_demand[p] > 0]
        if others:
            target = max(others, key=lambda p: (state.phase_demand[p], -p))
            return ShieldDecision(target, MAX_GREEN)

    if cfg.spillback > 0 and state.blocked_links:
        served = state.phase_links[requested] & state.links_with_demand
        if served and served <= state.blocked_links:

            def moves(p: int) -> bool:
                return bool((state.phase_links[p] & state.links_with_demand) - state.blocked_links)

            others = [p for p in range(state.n_phases) if p != requested and moves(p)]
            if others:
                target = max(others, key=lambda p: (state.phase_demand[p], -p))
                return ShieldDecision(target, SPILLBACK)

    return ShieldDecision(requested, reason)

