def classify(gaps: list[float]) -> str:
    mean = float(np.mean(gaps))
    if mean <= 1.0:
        return BETTER
    if mean > 3.0 or all(g > 1.0 for g in gaps):
        return WORSE
    return UNCERTAIN

def holm(pvalues: Sequence[float]) -> list[float]:
    """Holm-Bonferroni adjusted p-values (NaN entries are left out of the family)."""
    p = np.asarray(pvalues, dtype=float)
    out = np.full(p.shape, np.nan)
    idx = np.where(~np.isnan(p))[0]
    m = idx.size
    if m == 0:
        return out.tolist()
    order = idx[np.argsort(p[idx])]
    running = 0.0
    for rank, i in enumerate(order):
        running = max(running, min(1.0, (m - rank) * p[i]))
        out[i] = running
    return out.tolist()

def criteria(df: pd.DataFrame) -> pd.DataFrame:
    """Mean gap (%) of each controller to the best of the five, per criterion."""
    cells = {k: g for k, g in df.groupby(["network", "scenario", "demand"])}
    main = [k for k in cells if k[0] != "grid8x8" and k[1] in SCEN and k[1] not in (
        "sensor_noise", "comm_dropout_30", "buses")]  # fmt: skip
    spec = {
        "Trajet (14 cases)": [(k, "mean_travel_time") for k in main],
        "Attente (14 cases)": [(k, "mean_waiting_time") for k in main],
        "Ambulances (4 cases)": [(k, "ev_delay") for k in main if k[1] == "emergency"],
        "Piétons (2 cases)": [(k, "ped_mean_waiting_time") for k in main if k[1] == "pedestrians"],
        "Capteurs bruités": [(("grid4x4", "sensor_noise", "peak"), m)
                             for m in ("mean_travel_time", "mean_waiting_time")],
    }  # fmt: skip
    out = {}
    for crit, items in spec.items():
        gaps = {name: [] for _, _, name in CONTROLLERS}
        for key, metric in items:
            values = {n: cell_mean(cells[key], m, p, metric) for m, p, n in CONTROLLERS}
            best = min(values.values())
            for n, v in values.items():
                gaps[n].append(100 * (v - best) / best)
        out[crit] = {n: float(np.mean(g)) for n, g in gaps.items()}
    return pd.DataFrame(out)

def ambulance_counts(df: pd.DataFrame, demand: str) -> dict:
    """How many emergency vehicles the candidate gets through faster than Max-Pressure
    (same vehicle, same test seed), with the three training runs and with run 1 (the demo)."""
    cell = df[(df.network == "grid4x4") & (df.scenario == "emergency") & (df.demand == demand)]
    mp = cell[cell.method == "mp"].set_index("seed")

    def parse(s) -> dict[str, float]:
        return {k: float(v) for k, v in (x.split(":") for x in str(s).split())}

    gains: dict[int, list[float]] = {1: [], 2: [], 3: []}
    for _, r in cell[(cell.method == "hybrid_h2") & (cell.param == 4.0)].iterrows():
        dc, dm = parse(r.ev_delays), parse(mp.loc[r.seed, "ev_delays"])
        gains[int(r.run)] += [dm[e] - dc[e] for e in dc if e in dm]
    every = np.concatenate([np.array(g) for g in gains.values()])
    run1 = np.array(gains[1])
    return {
        "faster": int((every > 0).sum()), "total": int(every.size),
        "medianGainS": round(float(np.median(every)), 1),
        "run1Faster": int((run1 > 0).sum()), "run1Total": int(run1.size),
    }  # fmt: skip

def bias_logits(self, env, agents: list[str], logits: np.ndarray) -> np.ndarray:
    """The steps of ``act`` for a policy that owns the logits (the hybrid controller of
    the combined study): advice activation and expiry, a call when one is due, then
    the LLM bias on a copy of ``logits`` (one row per agent of ``agents``)."""
    from cotraffic.llm.situation import events

    now = env.now
    ready = [a for a in self.pending if a.start <= now]
    self.pending = [a for a in self.pending if a.start > now]
    self.active = [a for a in self.active + ready if a.end > now]
    latest: dict[str, Active] = {}
    for a in self.active:
        if a.junction not in latest or a.call >= latest[a.junction].call:
            latest[a.junction] = a
    self.active = list(latest.values())
    trigger = self._trigger(env, events(env))
    if trigger is not None:
        self._ask(env, trigger)
    out = np.array(logits, dtype=float, copy=True)
    index = {a: i for i, a in enumerate(agents)}
    for a in self.active:
        i = index.get(a.junction)
        if i is not None and a.phase < out.shape[1]:
            out[i, a.phase] += self.cfg.beta * a.weight
            self.biased_decisions += 1
    self.changed_decisions += int(
        (out.argmax(axis=1) != np.asarray(logits).argmax(axis=1)).sum()
    )
    return out

def network_state(env) -> dict[str, Any]:
    """What the strategist reads: network-level counts, from the controllers' own sensors."""
    halted_by = {
        tid: float(sum(env.meas.halting.get(ln, 0.0) for ln in inter.in_lanes))
        for tid, inter in env.intersections.items()
    }
    peds = {
        tid: int(sum(env.ped_waiting.get(c, 0.0) for c in inter.crossings))
        for tid, inter in env.intersections.items()
    }
    worst = max(halted_by, key=halted_by.get) if halted_by else ""
    return {
        "junctions": len(halted_by),
        "vehicles": int(env.conn.vehicle.getIDCount()),
        "halted": round(sum(halted_by.values())),
        "backlog": insertion_backlog(env),
        "queue_mean": round(sum(halted_by.values()) / max(1, len(halted_by)), 1),
        "queue_max": round(halted_by.get(worst, 0.0)),
        "queue_max_at": worst,
        "long_queues": sum(v >= LONG_QUEUE for v in halted_by.values()),
        "pedestrians": sum(peds.values()),
        "events": network_events(env),
    }

def act(self, env, obs: dict[str, Any]) -> dict[str, int]:
    self.strategy.update(env)
    self.mp_beta = self.beta if self.strategy.current == "equilibre" else 0.0
    return super().act(env, obs)
